function addToCart(m:Med){if(expired(m)){toast.error('Expired medicines cannot be billed.');return false;}if(m.price<=0||(m.needsReview&&m.unit==='Unit')||m.stock<=0){setEdit({...m});toast('Enter the selling price, selling unit and available stock, then select this medicine again.');return false;}setCart(c=>{const item=c.find(x=>x.id===m.id);if((item?.qty||0)>=m.stock){toast.error('Not enough stock.');return c}return item?c.map(x=>x.id===m.id?{...x,qty:x.qty+1}:x):[...c,{...m,qty:1}]});return true;}
